From 9aee1791f4cbdba62f714ff1d32c69b6e38f2eac Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 08:51:53 +0100
Subject: [PATCH] controls/LegendLayout: don't shrink items without a maximum
 width to zero

An item that doesn't set LegendLayout.maximumWidth was clamped to the
unset value of 0, so its content overflowed its cell. In right-to-left
layouts it overflowed to the left over the previous item; now it isn't.

BUG: 516577
---
 controls/LegendLayout.cpp | 6 +++++-
 1 file changed, 5 insertions(+), 1 deletion(-)

diff --git a/controls/LegendLayout.cpp b/controls/LegendLayout.cpp
index 1ca44f5..ae74fa8 100644
--- a/controls/LegendLayout.cpp
+++ b/controls/LegendLayout.cpp
@@ -162,7 +162,11 @@ void LegendLayout::updatePolish()
         auto y = (itemHeight + m_verticalSpacing) * row;

         item->setPosition(QPointF{x, y});
-        item->setWidth(std::clamp(itemWidth, attached->minimumWidth(), attached->maximumWidth()));
+        auto width = itemWidth;
+        if (attached->isMaximumWidthValid()) {
+            width = std::min(width, attached->maximumWidth());
+        }
+        item->setWidth(std::max(width, attached->minimumWidth()));

         // If we are in single column mode, we are most likely width constrained.
         // In that case, we should make sure items do not exceed our own width,
-- 
